public struct FfiConverterTypeDromeStore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = DromeStore

    public static func lift(_ handle: UInt64) throws -> DromeStore {
        return DromeStore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: DromeStore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DromeStore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: DromeStore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


