/**
 * A caller-captured moment: absolute time plus the UTC offset in effect where
 * (and when) it was captured. Local wall time = `epoch_secs + tz_offset_secs`.
 */
public struct LocalInstant: Equatable, Hashable {
    public var epochSecs: Int64
    public var tzOffsetSecs: Int32

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(epochSecs: Int64, tzOffsetSecs: Int32) {
        self.epochSecs = epochSecs
        self.tzOffsetSecs = tzOffsetSecs
    }

    

    
}

