@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLocalInstant: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LocalInstant {
        return
            try LocalInstant(
                epochSecs: FfiConverterInt64.read(from: &buf), 
                tzOffsetSecs: FfiConverterInt32.read(from: &buf)
        )
    }

    public static func write(_ value: LocalInstant, into buf: inout [UInt8]) {
        FfiConverterInt64.write(value.epochSecs, into: &buf)
        FfiConverterInt32.write(value.tzOffsetSecs, into: &buf)
    }
}


