/**
 * Crate-wide error type. Crossed to Swift as a flat error (variant + message).
 */
public 
enum UniDromeError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Database(message: String)
    
    case Serialization(message: String)
    
    case InvalidDate(message: String)
    
    case InvalidArgument(message: String)
    
    case NoActiveChallenge(message: String)
    
    case ActiveChallengeExists(message: String)
    
    case EventNotFound(message: String)
    
    case TaskNotRevocable(message: String)
    
    case UnknownExtra(message: String)
    
    case TimeOutOfRange(message: String)
    
    case Internal(message: String)
    

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension UniDromeError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeUniDromeError: FfiConverterRustBuffer {
    typealias SwiftType = UniDromeError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> UniDromeError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Database(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .Serialization(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .InvalidDate(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .InvalidArgument(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .NoActiveChallenge(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .ActiveChallengeExists(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .EventNotFound(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .TaskNotRevocable(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 9: return .UnknownExtra(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 10: return .TimeOutOfRange(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 11: return .Internal(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: UniDromeError, into buf: inout [UInt8]) {
        switch value {

        

        
        case .Database(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .Serialization(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
        case .InvalidDate(_ /* message is ignored*/):
            writeInt(&buf, Int32(3))
        case .InvalidArgument(_ /* message is ignored*/):
            writeInt(&buf, Int32(4))
        case .NoActiveChallenge(_ /* message is ignored*/):
            writeInt(&buf, Int32(5))
        case .ActiveChallengeExists(_ /* message is ignored*/):
            writeInt(&buf, Int32(6))
        case .EventNotFound(_ /* message is ignored*/):
            writeInt(&buf, Int32(7))
        case .TaskNotRevocable(_ /* message is ignored*/):
            writeInt(&buf, Int32(8))
        case .UnknownExtra(_ /* message is ignored*/):
            writeInt(&buf, Int32(9))
        case .TimeOutOfRange(_ /* message is ignored*/):
            writeInt(&buf, Int32(10))
        case .Internal(_ /* message is ignored*/):
            writeInt(&buf, Int32(11))

        
        }
    }
}


